root_black_0e0e0e_charcoal_1a1a1a_gold:
:root {
  --black: #0e0e0e;
  --charcoal: #1a1a1a;
  --gold: #c9a96e;
  --gold-light: #e8d5b0;
  --cream: #f8f4ef;
  --warm-white: #fdfaf6;
  --text-dark: #2c2c2c;
  --text-light: #7a7268;
  --border: rgba(201,169,110,0.25);
  --nav-height: 80px;
}
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: 'Montserrat', sans-serif;
  background: var(--warm-white);
  color: var(--text-dark);
  overflow-x: hidden;
}

/* ─── SCROLLBAR ─── */
::-webkit-scrollbar { width: 5px; }
::-webkit-scrollbar-track { background: var(--black); }
::-webkit-scrollbar-thumb { background: var(--gold); }

/* ─── NOISE TEXTURE OVERLAY ─── */
body::before {
  content: '';
  position: fixed;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.04'/%3E%3C/svg%3E");
  pointer-events: none;
  z-index: 9999;
  opacity: 0.4;
}

/* ─── NAV ─── */
nav {
  position: fixed;
  top: 0; left: 0; right: 0;
  height: var(--nav-height);
  background: rgba(14,14,14,0.96);
  backdrop-filter: blur(20px);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 4vw;
  border-bottom: 1px solid var(--border);
}
.nav-logo {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
}
.nav-logo-svg { height: 42px; }
.nav-logo-text {
  font-family: 'Playfair Display', serif;
  font-size: 1.6rem;
  letter-spacing: 0.18em;
  color: var(--gold);
  font-weight: 400;
}
.nav-links {
  display: flex;
  gap: 2rem;
  list-style: none;
  align-items: center;
}
.nav-links a {
  font-size: 0.7rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.7);
  text-decoration: none;
  transition: color 0.3s;
  position: relative;
}
.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0; right: 0;
  height: 1px;
  background: var(--gold);
  transform: scaleX(0);
  transition: transform 0.3s;
}
.nav-links a:hover { color: var(--gold); }
.nav-links a:hover::after { transform: scaleX(1); }
.nav-cta {
  background: var(--gold);
  color: var(--black) !important;
  padding: 8px 20px;
  letter-spacing: 0.15em;
  font-weight: 600 !important;
}
.nav-cta:hover { background: var(--gold-light) !important; color: var(--black) !important; }
.nav-cta::after { display: none !important; }
.hamburger {
  display: none;
  flex-direction: column;
  cursor: pointer;
  gap: 5px;
}
.hamburger span {
  width: 24px;
  height: 1px;
  background: var(--gold);
  transition: all 0.3s;
}

/* ─── MOBILE NAV ─── */
.mobile-menu {
  display: none;
  position: fixed;
  inset: 0;
  background: var(--black);
  z-index: 999;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2rem;
}
.mobile-menu.open { display: flex; }
.mobile-menu a {
  font-family: 'Playfair Display', serif;
  font-size: 2rem;
  color: var(--cream);
  text-decoration: none;
  letter-spacing: 0.1em;
  transition: color 0.3s;
}
.mobile-menu a:hover { color: var(--gold); }
.close-menu {
  position: absolute;
  top: 28px;
  right: 4vw;
  font-size: 1.8rem;
  color: var(--gold);
  cursor: pointer;
  background: none;
  border: none;
}

/* ─── HERO ─── */
#accueil {
  height: 100vh;
  background: var(--black);
  display: grid;
  grid-template-columns: 1fr 1fr;
  position: relative;
  overflow: hidden;
  padding-top: var(--nav-height);
}
.hero-left {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 6vw 5vw 6vw 8vw;
  position: relative;
  z-index: 2;
}
.hero-tag {
  font-size: 0.65rem;
  letter-spacing: 0.35em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 2rem;
  display: flex;
  align-items: center;
  gap: 12px;
}
.hero-tag::before {
  content: '';
  width: 40px;
  height: 1px;
  background: var(--gold);
}
.hero-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(3.5rem, 7vw, 7rem);
  line-height: 0.95;
  color: var(--warm-white);
  letter-spacing: -0.02em;
  margin-bottom: 2rem;
}
.hero-title em {
  font-style: italic;
  color: var(--gold);
  display: block;
}
.hero-sub {
  font-size: 0.8rem;
  letter-spacing: 0.12em;
  color: rgba(255,255,255,0.5);
  line-height: 1.8;
  max-width: 380px;
  margin-bottom: 3rem;
}
.hero-actions { display: flex; gap: 1rem; flex-wrap: wrap; }
.btn-primary {
  background: var(--gold);
  color: var(--black);
  padding: 14px 36px;
  font-size: 0.7rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.3s;
  font-family: 'Montserrat', sans-serif;
  border: none;
  cursor: pointer;
}
.btn-primary:hover { background: var(--gold-light); transform: translateY(-2px); }
.btn-outline {
  border: 1px solid rgba(255,255,255,0.3);
  color: rgba(255,255,255,0.7);
  padding: 14px 36px;
  font-size: 0.7rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  font-weight: 500;
  text-decoration: none;
  transition: all 0.3s;
  font-family: 'Montserrat', sans-serif;
}
.btn-outline:hover { border-color: var(--gold); color: var(--gold); }
.hero-right {
  position: relative;
  overflow: hidden;
}
.hero-right::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(201,169,110,0.08) 0%, transparent 60%);
  z-index: 1;
}
.hero-image-placeholder {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: flex;
  align-items: center;
  justify-content: center;
}
.hero-grid-bg {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(201,169,110,0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(201,169,110,0.05) 1px, transparent 1px);
  background-size: 60px 60px;
}
.hero-big-k {
  position: absolute;
  right: -5%;
  top: 50%;
  transform: translateY(-50%);
  font-family: 'Playfair Display', serif;
  font-size: 40vw;
  color: rgba(201,169,110,0.04);
  letter-spacing: -0.05em;
  line-height: 1;
  user-select: none;
  z-index: 0;
}
.hero-stats {
  position: absolute;
  bottom: 6vh;
  left: 8vw;
  display: flex;
  gap: 3rem;
  z-index: 3;
}
.stat { text-align: left; }
.stat-num {
  font-family: 'Playfair Display', serif;
  font-size: 2.2rem;
  color: var(--gold);
  font-weight: 400;
}
.stat-label {
  font-size: 0.6rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.4);
  margin-top: 2px;
}
.scroll-hint {
  position: absolute;
  bottom: 6vh;
  right: 4vw;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  color: rgba(255,255,255,0.3);
  font-size: 0.6rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  z-index: 3;
}
.scroll-line {
  width: 1px;
  height: 50px;
  background: linear-gradient(to bottom, var(--gold), transparent);
  animation: scrollAnim 2s ease-in-out infinite;
}
@keyframes scrollAnim { 0%,100%{opacity:1;transform:scaleY(1)} 50%{opacity:0.5;transform:scaleY(0.5)} }

/* ─── SECTION COMMON ─── */
section { position: relative; }
.section-tag {
  font-size: 0.6rem;
  letter-spacing: 0.35em;
  text-transform: uppercase;
  color: var(--gold);
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 1.2rem;
}
.section-tag::before {
  content: '';
  width: 30px;
  height: 1px;
  background: var(--gold);
}
.section-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(2rem, 4vw, 3.5rem);
  line-height: 1.1;
  margin-bottom: 1.5rem;
}
.section-title em { font-style: italic; color: var(--gold); }

/* ─── ABOUT / INTRO ─── */
.about-section {
  padding: 8rem 8vw;
  background: var(--warm-white);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6vw;
  align-items: center;
}
.about-visual {
  position: relative;
}
.about-card {
  background: var(--black);
  padding: 3rem;
  position: relative;
  overflow: hidden;
}
.about-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0;
  width: 3px;
  height: 100%;
  background: linear-gradient(to bottom, var(--gold), transparent);
}
.about-card-title {
  font-family: 'Playfair Display', serif;
  font-size: 1.8rem;
  color: var(--warm-white);
  margin-bottom: 1rem;
  font-style: italic;
}
.about-card-text {
  font-size: 0.8rem;
  color: rgba(255,255,255,0.5);
  line-height: 1.9;
}
.about-badge {
  position: absolute;
  top: -20px;
  right: -20px;
  width: 100px;
  height: 100px;
  background: var(--gold);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  font-family: 'Playfair Display', serif;
  font-size: 0.9rem;
  color: var(--black);
  text-align: center;
  line-height: 1.2;
  font-weight: 700;
  box-shadow: 0 10px 40px rgba(201,169,110,0.4);
}
.about-text p {
  font-size: 0.85rem;
  line-height: 1.9;
  color: var(--text-light);
  margin-bottom: 1.2rem;
}
.about-name {
  font-family: 'Playfair Display', serif;
  font-size: 1.3rem;
  color: var(--text-dark);
  font-style: italic;
  margin-top: 2rem;
}
.about-role {
  font-size: 0.65rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gold);
  margin-top: 4px;
}

/* ─── MARCAS ─── */
#marcas {
  padding: 5rem 8vw;
  background: var(--black);
  overflow: hidden;
}
.marcas-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 3rem;
}
.marcas-sub {
  font-size: 0.8rem;
  color: rgba(255,255,255,0.4);
  max-width: 300px;
  line-height: 1.7;
}
.marcas-track-wrap {
  overflow: hidden;
  mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent);
}
.marcas-track {
  display: flex;
  gap: 2px;
  animation: scrollTrack 20s linear infinite;
  width: max-content;
}
@keyframes scrollTrack { from{transform:translateX(0)} to{transform:translateX(-50%)} }
.marca-pill {
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(201,169,110,0.15);
  padding: 1rem 2.5rem;
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: 10px;
  transition: all 0.3s;
}
.marca-pill:hover {
  background: rgba(201,169,110,0.08);
  border-color: var(--gold);
}
.marca-dot {
  width: 6px;
  height: 6px;
  background: var(--gold);
  border-radius: 50%;
}
.marca-name {
  font-size: 0.7rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.6);
  font-weight: 500;
}
.marcas-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  margin-top: 3rem;
  background: rgba(201,169,110,0.1);
}
.marca-card {
  background: var(--charcoal);
  padding: 2rem;
  text-align: center;
  transition: all 0.4s;
  cursor: default;
}
.marca-card:hover {
  background: rgba(201,169,110,0.08);
  transform: translateY(-4px);
}
.marca-initial {
  font-family: 'Playfair Display', serif;
  font-size: 2.5rem;
  color: var(--gold);
  font-weight: 400;
  line-height: 1;
  margin-bottom: 0.5rem;
}
.marca-card-name {
  font-size: 0.65rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.4);
}
.marca-card-desc {
  font-size: 0.7rem;
  color: rgba(255,255,255,0.25);
  margin-top: 8px;
  line-height: 1.6;
}

/* ─── produits / BOUTIQUE ─── */
#produits {
  padding: 8rem 8vw;
  background: var(--cream);
}
.produits-header {
  text-align: center;
  margin-bottom: 4rem;
}
.boutique-notice {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--black);
  color: var(--gold);
  padding: 10px 24px;
  font-size: 0.65rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  margin-bottom: 1.5rem;
}
.notice-dot { width: 8px; height: 8px; background: var(--gold); border-radius: 50%; animation: pulse 2s infinite; }
@keyframes pulse { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:0.5;transform:scale(0.8)} }
.products-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}
.product-card {
  background: white;
  position: relative;
  overflow: hidden;
  transition: all 0.4s;
  box-shadow: 0 4px 20px rgba(0,0,0,0.06);
}
.product-card:hover { transform: translateY(-6px); box-shadow: 0 20px 50px rgba(0,0,0,0.12); }
.product-img {
  aspect-ratio: 4/3;
  background: var(--black);
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.product-icon-bg {
  font-size: 4rem;
  opacity: 0.2;
  color: var(--gold);
}
.product-gradient {
  position: absolute;
  inset: 0;
}
.product-instore {
  position: absolute;
  top: 12px;
  right: 12px;
  background: var(--gold);
  color: var(--black);
  padding: 4px 12px;
  font-size: 0.55rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  font-weight: 600;
}
.product-body { padding: 1.5rem; }
.product-cat {
  font-size: 0.6rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 0.5rem;
}
.product-name {
  font-family: 'Playfair Display', serif;
  font-size: 1.1rem;
  color: var(--text-dark);
  margin-bottom: 0.5rem;
}
.product-desc {
  font-size: 0.75rem;
  color: var(--text-light);
  line-height: 1.7;
  margin-bottom: 1rem;
}
.product-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 1rem;
  border-top: 1px solid var(--border);
}
.product-price {
  font-family: 'Playfair Display', serif;
  font-size: 1.3rem;
  color: var(--text-dark);
}
.product-avail {
  font-size: 0.6rem;
  letter-spacing: 0.15em;
  color: var(--text-light);
  text-transform: uppercase;
}

/* ─── PELUQUERÍA / prixS ─── */
#peluqueria {
  padding: 8rem 8vw;
  background: var(--black);
}
.peluqueria-header {
  margin-bottom: 4rem;
}
.price-categories {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background: rgba(201,169,110,0.1);
}
.price-cat {
  background: var(--charcoal);
  padding: 2.5rem;
  transition: background 0.3s;
}
.price-cat:hover { background: rgba(201,169,110,0.06); }
.price-cat-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 1.5rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid rgba(201,169,110,0.15);
}
.price-cat-icon {
  width: 36px;
  height: 36px;
  background: rgba(201,169,110,0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
}
.price-cat-name {
  font-family: 'Playfair Display', serif;
  font-size: 1.1rem;
  color: var(--warm-white);
  font-style: italic;
}
.price-item {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 0.5rem 0;
  border-bottom: 1px dashed rgba(255,255,255,0.05);
}
.price-item:last-child { border: none; }
.price-service {
  font-size: 0.75rem;
  color: rgba(255,255,255,0.5);
}
.price-value {
  font-family: 'Cormorant Garamond', serif;
  font-size: 0.9rem;
  color: var(--gold);
  white-space: nowrap;
  margin-left: 1rem;
}
.price-note {
  font-size: 0.65rem;
  color: rgba(255,255,255,0.25);
  font-style: italic;
  margin-top: 1rem;
}
.price-cta-row {
  text-align: center;
  margin-top: 3rem;
}

/* ─── NOTICIAS ─── */
#noticias {
  padding: 8rem 8vw;
  background: var(--warm-white);
}
.noticias-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 1.5rem;
  margin-top: 3rem;
}
.noticia-card {
  background: white;
  overflow: hidden;
  box-shadow: 0 4px 20px rgba(0,0,0,0.05);
  transition: all 0.4s;
}
.noticia-card:hover { transform: translateY(-4px); box-shadow: 0 15px 40px rgba(0,0,0,0.1); }
.noticia-img {
  aspect-ratio: 16/9;
  background: var(--black);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  position: relative;
  overflow: hidden;
}
.noticia-card.featured .noticia-img { aspect-ratio: 16/10; }
.noticia-body { padding: 1.5rem; }
.noticia-cat {
  font-size: 0.6rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 0.5rem;
}
.noticia-title {
  font-family: 'Playfair Display', serif;
  font-size: 1.1rem;
  color: var(--text-dark);
  line-height: 1.3;
  margin-bottom: 0.5rem;
}
.noticia-card.featured .noticia-title { font-size: 1.4rem; }
.noticia-excerpt {
  font-size: 0.75rem;
  color: var(--text-light);
  line-height: 1.7;
  margin-bottom: 1rem;
}
.noticia-date {
  font-size: 0.6rem;
  letter-spacing: 0.1em;
  color: rgba(0,0,0,0.3);
  text-transform: uppercase;
}

/* ─── TESTIMONIALS ─── */
.testimonials-section {
  padding: 7rem 8vw;
  background: var(--black);
  position: relative;
  overflow: hidden;
}
.testimonials-section::before {
  content: '"';
  position: absolute;
  top: -2rem;
  left: 5vw;
  font-family: 'Playfair Display', serif;
  font-size: 25rem;
  color: rgba(201,169,110,0.04);
  line-height: 1;
  pointer-events: none;
}
.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  margin-top: 3rem;
  position: relative;
  z-index: 1;
}
.testimonial-card {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(201,169,110,0.1);
  padding: 2.5rem;
  position: relative;
  transition: all 0.4s;
}
.testimonial-card:hover {
  background: rgba(201,169,110,0.06);
  border-color: rgba(201,169,110,0.3);
  transform: translateY(-4px);
}
.testimonial-stars {
  display: flex;
  gap: 4px;
  margin-bottom: 1.2rem;
}
.star { color: var(--gold); font-size: 0.8rem; }
.testimonial-text {
  font-family: 'Cormorant Garamond', serif;
  font-size: 1.05rem;
  color: rgba(255,255,255,0.7);
  line-height: 1.8;
  font-style: italic;
  margin-bottom: 1.5rem;
}
.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}
.author-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--gold);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Playfair Display', serif;
  font-size: 1rem;
  color: var(--black);
  font-weight: 700;
}
.author-name {
  font-size: 0.75rem;
  font-weight: 600;
  color: rgba(255,255,255,0.8);
}
.author-detail {
  font-size: 0.6rem;
  color: rgba(255,255,255,0.3);
  letter-spacing: 0.1em;
}

/* ─── contact ─── */
#contact {
  padding: 8rem 8vw;
  background: var(--cream);
}
.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5vw;
  margin-top: 3rem;
}
.contact-info { }
.info-block {
  margin-bottom: 2.5rem;
}
.info-block-label {
  font-size: 0.6rem;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 0.6rem;
}
.info-block-value {
  font-family: 'Playfair Display', serif;
  font-size: 1.1rem;
  color: var(--text-dark);
  line-height: 1.5;
}
.hours-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.4rem 2rem;
  margin-top: 0.5rem;
}
.hours-day {
  font-size: 0.75rem;
  color: var(--text-light);
}
.hours-time {
  font-size: 0.75rem;
  color: var(--text-dark);
  font-weight: 500;
}
.map-container {
  background: var(--black);
  aspect-ratio: 4/3;
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.map-iframe {
  width: 100%;
  height: 100%;
  border: none;
  filter: grayscale(40%) contrast(1.1);
}
.wa-button {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  background: #25D366;
  color: white;
  padding: 14px 32px;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  text-decoration: none;
  transition: all 0.3s;
  margin-top: 1.5rem;
  font-family: 'Montserrat', sans-serif;
}
.wa-button:hover { background: #1da851; transform: translateY(-2px); }
.wa-icon {
  font-size: 1.2rem;
}
.social-links {
  display: flex;
  gap: 1rem;
  margin-top: 1.5rem;
}
.social-link {
  width: 44px;
  height: 44px;
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
  color: var(--text-dark);
  font-size: 1rem;
  transition: all 0.3s;
}
.social-link:hover {
  background: var(--black);
  color: var(--gold);
  border-color: var(--gold);
}

/* ─── FOOTER ─── */
footer {
  background: var(--black);
  padding: 4rem 8vw 2rem;
  border-top: 1px solid var(--border);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3vw;
  margin-bottom: 3rem;
}
.footer-brand .footer-logo-text {
  font-family: 'Playfair Display', serif;
  font-size: 2rem;
  letter-spacing: 0.25em;
  color: var(--gold);
  margin-bottom: 1rem;
  display: block;
}
.footer-brand-desc {
  font-size: 0.75rem;
  color: rgba(255,255,255,0.3);
  line-height: 1.8;
  max-width: 260px;
}
.footer-col-title {
  font-size: 0.6rem;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 1.2rem;
}
.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}
.footer-links a {
  font-size: 0.75rem;
  color: rgba(255,255,255,0.35);
  text-decoration: none;
  transition: color 0.3s;
  letter-spacing: 0.05em;
}
.footer-links a:hover { color: var(--gold); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.06);
  padding-top: 1.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.footer-copy {
  font-size: 0.65rem;
  color: rgba(255,255,255,0.2);
}
.footer-credit {
  font-size: 0.6rem;
  color: rgba(255,255,255,0.15);
  letter-spacing: 0.1em;
}
.footer-credit a {
  color: rgba(201,169,110,0.4);
  text-decoration: none;
  transition: color 0.3s;
}
.footer-credit a:hover { color: var(--gold); }

/* ─── WA FLOATING ─── */
.wa-float {
  position: fixed;
  bottom: 30px;
  right: 30px;
  width: 60px;
  height: 60px;
  background: #25D366;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 500;
  text-decoration: none;
  box-shadow: 0 8px 30px rgba(37,211,102,0.4);
  transition: all 0.3s;
  animation: floatBounce 3s ease-in-out infinite;
}
.wa-float:hover { transform: scale(1.1); box-shadow: 0 12px 40px rgba(37,211,102,0.6); }
@keyframes floatBounce { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-6px)} }
.wa-float svg { width: 30px; height: 30px; fill: white; }
.wa-tooltip {
  position: absolute;
  right: 70px;
  background: var(--black);
  color: white;
  padding: 8px 14px;
  font-size: 0.7rem;
  white-space: nowrap;
  border: 1px solid var(--border);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s;
  font-family: 'Montserrat', sans-serif;
}
.wa-float:hover .wa-tooltip { opacity: 1; }

/* ─── ANIMATIONS ─── */
.fade-in {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.8s ease, transform 0.8s ease;
}
.fade-in.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ─── RESPONSIVE ─── */
@media (max-width: 1024px) {
  .marcas-grid { grid-template-columns: repeat(2, 1fr); }
  .price-categories { grid-template-columns: 1fr 1fr; }
  .noticias-grid { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 768px) {
  :root { --nav-height: 64px; }
  .nav-links { display: none; }
  .hamburger { display: flex; }
  #accueil { grid-template-columns: 1fr; height: auto; padding-bottom: 4rem; }
  .hero-right { display: none; }
  .hero-big-k { display: none; }
  .hero-stats { position: static; margin-top: 3rem; gap: 2rem; }
  .about-section { grid-template-columns: 1fr; padding: 5rem 6vw; }
  .products-grid { grid-template-columns: 1fr 1fr; }
  .price-categories { grid-template-columns: 1fr; }
  .noticias-grid { grid-template-columns: 1fr; }
  .testimonials-grid { grid-template-columns: 1fr; }
  .contact-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .footer-bottom { flex-direction: column; gap: 8px; text-align: center; }
  .marcas-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 480px) {
  .products-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .marcas-grid { grid-template-columns: 1fr 1fr; }
  .hero-actions { flex-direction: column; }
  .btn-primary, .btn-outline { text-align: center; }
}

/* ─── CHAT BOOKING WIDGET ─── */
.chat-fab {
  position: fixed;
  bottom: 30px;
  right: 102px;
  width: 60px;
  height: 60px;
  background: linear-gradient(135deg, var(--gold), #b8935a);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 500;
  cursor: pointer;
  border: none;
  box-shadow: 0 8px 30px rgba(201,169,110,0.5);
  transition: all 0.3s;
  animation: floatBounce 3s ease-in-out infinite 1.5s;
}
.chat-fab:hover { transform: scale(1.1); box-shadow: 0 12px 40px rgba(201,169,110,0.7); }
.chat-fab svg { width: 26px; height: 26px; fill: var(--black); }
.chat-fab-tooltip {
  position: absolute;
  right: 70px;
  background: var(--black);
  color: white;
  padding: 8px 14px;
  font-size: 0.7rem;
  white-space: nowrap;
  border: 1px solid var(--border);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s;
  font-family: 'Montserrat', sans-serif;
}
.chat-fab:hover .chat-fab-tooltip { opacity: 1; }
.chat-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.55);
  z-index: 2000;
  display: none;
  align-items: flex-end;
  justify-content: flex-end;
  padding: 24px;
  backdrop-filter: blur(4px);
}
.chat-overlay.open { display: flex; }
.chat-window {
  width: 380px;
  height: 590px;
  background: var(--warm-white);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-shadow: 0 30px 80px rgba(0,0,0,0.5);
  animation: chatSlideUp 0.3s ease;
}
@keyframes chatSlideUp { from{transform:translateY(20px);opacity:0} to{transform:translateY(0);opacity:1} }
.chat-header {
  background: var(--black);
  padding: 1rem 1.2rem;
  display: flex;
  align-items: center;
  gap: 12px;
  border-bottom: 1px solid var(--border);
  flex-shrink: 0;
}
.chat-avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: var(--gold);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Playfair Display', serif;
  font-size: 1.1rem;
  color: var(--black);
  font-weight: 700;
  flex-shrink: 0;
}
.chat-header-info { flex: 1; }
.chat-header-name { font-family: 'Playfair Display', serif; font-size: 0.95rem; color: var(--warm-white); }
.chat-header-status { font-size: 0.6rem; letter-spacing: 0.15em; color: #25D366; text-transform: uppercase; margin-top: 2px; }
.chat-close { background: none; border: none; color: rgba(255,255,255,0.4); font-size: 1.3rem; cursor: pointer; padding: 4px; transition: color 0.3s; }
.chat-close:hover { color: var(--gold); }
.chat-messages {
  flex: 1;
  overflow-y: auto;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  background: var(--warm-white);
}
.chat-messages::-webkit-scrollbar { width: 3px; }
.chat-messages::-webkit-scrollbar-thumb { background: var(--gold); }
.msg { display: flex; gap: 8px; align-items: flex-end; }
.msg.bot { flex-direction: row; }
.msg.user { flex-direction: row-reverse; }
.msg-av {
  width: 28px; height: 28px; border-radius: 50%; background: var(--gold);
  display: flex; align-items: center; justify-content: center;
  font-size: 0.65rem; color: var(--black); font-weight: 700; flex-shrink: 0;
}
.msg-bubble {
  max-width: 78%;
  padding: 0.65rem 0.9rem;
  font-size: 0.77rem;
  line-height: 1.65;
  font-family: 'Montserrat', sans-serif;
}
.msg.bot .msg-bubble { background: var(--black); color: rgba(255,255,255,0.85); }
.msg.user .msg-bubble { background: var(--gold); color: var(--black); font-weight: 500; }
.chat-options {
  padding: 0.7rem 1rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  border-top: 1px solid var(--border);
  background: white;
  flex-shrink: 0;
  min-height: 52px;
}
.chat-opt {
  background: var(--black);
  color: var(--gold);
  border: 1px solid var(--border);
  padding: 5px 12px;
  font-size: 0.62rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
  font-family: 'Montserrat', sans-serif;
  transition: all 0.25s;
  white-space: nowrap;
}
.chat-opt:hover { background: var(--gold); color: var(--black); }
.chat-input-row {
  display: none;
  border-top: 1px solid var(--border);
  background: white;
  flex-shrink: 0;
}
.chat-inp {
  flex: 1;
  border: none;
  padding: 0.8rem 1rem;
  font-size: 0.78rem;
  font-family: 'Montserrat', sans-serif;
  outline: none;
  background: white;
  color: var(--text-dark);
}
.chat-inp::placeholder { color: var(--text-light); }
.chat-send-btn {
  background: var(--gold);
  border: none;
  padding: 0 1.2rem;
  cursor: pointer;
  color: var(--black);
  font-size: 1.1rem;
  transition: background 0.3s;
}
.chat-send-btn:hover { background: var(--gold-light); }
.typing-dots { display: flex; gap: 4px; align-items: center; padding: 3px 0; }
.typing-dots span {
  width: 6px; height: 6px; border-radius: 50%; background: var(--gold);
  animation: tdot 1.2s infinite;
}
.typing-dots span:nth-child(2) { animation-delay: 0.2s; }
.typing-dots span:nth-child(3) { animation-delay: 0.4s; }
@keyframes tdot { 0%,60%,100%{opacity:0.3;transform:scale(0.8)} 30%{opacity:1;transform:scale(1)} }
@media (max-width: 480px) {
  .chat-overlay { padding: 0; }
  .chat-window { width: 100%; height: 90vh; }
  .chat-fab { right: 90px; width: 52px; height: 52px; }
}
